INSERT INTO `comentario` (`idUsuario`, `idBestia`, `fechaPublicacion`, `contenido`) VALUES 
INSERT INTO `noticia` (`idNoticia`, `titulo`, `contenido`, `fechaPublicacion`, `idUsuario`) VALUES 
(1, 'Nueva expedición a Creta', 'Se ha financiado una nueva expedición arqueológica a la isla de Creta. El objetivo es explorar los niveles más profundos y recientemente descubiertos del Laberinto en busca de rastros biológicos y nuevas evidencias del Minotauro. Investigadores de todo el mundo están a la expectativa de los hallazgos.', '2026-08-01', 1),
(2, 'Alerta en la Península Arábiga', 'Satélites meteorológicos detectaron fuertes anomalías térmicas en la zona central del desierto de Arabia. Se sospecha un posible evento relacionado al ave Fénix. Se recomienda máxima precaución a los investigadores en la zona.', '2026-08-15', 2),
(3, 'Descubrimiento fósil anómalo', 'Hallados fósiles de gran tamaño en las montañas heladas del norte, exhibiendo extrañas marcas de vitrificación en los huesos. Esto podría cambiar la manera en que entendemos la capacidad biológica de los grandes reptiles.', '2026-08-20', 4),
(4, 'Sismos en el Peloponeso', 'Los recientes y persistentes movimientos sísmicos detectados en el sur de Grecia han llamado la atención de la comunidad criptozoológica. Se especula con la posible reactivación de redes de cuevas milenarias que podrían albergar entidades como el mismísimo Cerbero.', '2026-08-21', 1),
(5, 'El resurgir del folclore draconiano', 'Un reciente documental ha provocado que los avistamientos no confirmados de criaturas aladas en el este de Europa aumenten un 400%. Aunque la mayoría son confusiones con la fauna local, algunos testimonios resultan inexplicablemente precisos respecto a la mitología de los grandes reptiles.', '2026-08-22', 2),
(6, 'Biólogos marinos en alerta', 'Sonares de profundidad extrema han detectado firmas acústicas masivas cerca de la Fosa de las Marianas. Los patrones rítmicos no coinciden con las ballenas conocidas. Algunos expertos ya comienzan a discutir en foros cerrados sobre el mito del Leviatán.', '2026-08-24', 4);
